from sentry import eventstore, features, roles
from sentry.api.base import region_silo_endpoint
from sentry.api.bases.project import ProjectEndpoint, ProjectPermission
from sentry.api.serializers import serialize
from sentry.auth.superuser import is_active_superuser
from sentry.auth.system import is_system_auth
from sentry.constants import ATTACHMENTS_ROLE_DEFAULT
from sentry.models import EventAttachment, File, OrganizationMember


class EventAttachmentDetailsPermission(ProjectPermission):
    def has_object_permission(self, request: Request, view, project):
        result = super().has_object_permission(request, view, project)

        if not result:
            return result

        if is_system_auth(request.auth) or is_active_superuser(request):
            return True

        if not request.user.is_authenticated:
            return False

        organization = project.organization
        required_role = (
            organization.get_option("sentry:attachments_role") or ATTACHMENTS_ROLE_DEFAULT
        )

        try:
            om = OrganizationMember.objects.get(organization=organization, user_id=request.user.id)
        except OrganizationMember.DoesNotExist:
            return False

        required_role = roles.get(required_role)
        return any(
            role.priority >= required_role.priority for role in om.get_all_org_roles_sorted()
        )


@region_silo_endpoint
class EventAttachmentDetailsEndpoint(ProjectEndpoint):
    permission_classes = (EventAttachmentDetailsPermission,)

    def download(self, attachment):
        file = File.objects.get(id=attachment.file_id)
        fp = file.getfile()
        response = StreamingHttpResponse(
            iter(lambda: fp.read(4096), b""),
            content_type=file.headers.get("content-type", "application/octet-stream"),
        )
        response["Content-Length"] = file.size
        response["Content-Disposition"] = 'attachment; filename="%s"' % posixpath.basename(
            " ".join(attachment.name.split())
        )
        return response

    def get(self, request: Request, project, event_id, attachment_id) -> Response:
        """
        Retrieve an Attachment
        ``````````````````````

        :pparam string organization_slug: the slug of the organization the
                                          issues belong to.
        :pparam string project_slug: the slug of the project the event
                                     belongs to.
        :pparam string event_id: the id of the event.
        :pparam string attachment_id: the id of the attachment.
        :auth: required
        """
        if not features.has(
            "organizations:event-attachments", project.organization, actor=request.user
        ):
            return self.respond(status=404)

        event = eventstore.get_event_by_id(project.id, event_id)
        if event is None:
            return self.respond({"detail": "Event not found"}, status=404)

        try:
            attachment = EventAttachment.objects.filter(
                project_id=project.id, event_id=event.event_id, id=attachment_id
            ).get()
        except EventAttachment.DoesNotExist:
            return self.respond({"detail": "Attachment not found"}, status=404)

        if request.GET.get("download") is not None:
            return self.download(attachment)

        return self.respond(serialize(attachment, request.user))

    def delete(self, request: Request, project, event_id, attachment_id) -> Response:
        """
        Delete an Event Attachment by ID
        ````````````````````````````````

        Delete an attachment on the given event.

        :pparam string event_id: the identifier of the event.
        :pparam string attachment_id: the identifier of the attachment.
        :auth: required
        """
        if not features.has(
            "organizations:event-attachments", project.organization, actor=request.user
        ):
            return self.respond(status=404)

        try:
            attachment = EventAttachment.objects.filter(
                project_id=project.id, event_id=event_id, id=attachment_id
            ).get()
        except EventAttachment.DoesNotExist:
            return self.respond({"detail": "Attachment not found"}, status=404)

        attachment.delete()
        return self.respond(status=204)

from django.db.models import Q
from rest_framework.request import Request
from rest_framework.response import Response

from sentry import analytics
from sentry.api.base import region_silo_endpoint
from sentry.api.bases.organization import OrganizationEndpoint, OrganizationSearchPermission
from sentry.api.exceptions import ResourceDoesNotExist
from sentry.api.serializers import serialize
from sentry.api.serializers.rest_framework.savedsearch import (
    OrganizationSearchAdminSerializer,
    OrganizationSearchMemberSerializer,
)
from sentry.models.organization import Organization
from sentry.models.savedsearch import SavedSearch, Visibility
from sentry.models.search_common import SearchType


class OrganizationSearchEditPermission(OrganizationSearchPermission):
    """
    Includes object permission check to disallow users without org:write from
    mutating Visibility.ORGANIZATION searches.
    """

    def has_object_permission(self, request: Request, view, obj):
        if isinstance(obj, Organization):
            return super().has_object_permission(request, view, obj)

        if isinstance(obj, SavedSearch):
            return (
                request.access.has_scope("org:write") or obj.visibility != Visibility.ORGANIZATION
            )


@region_silo_endpoint
class OrganizationSearchDetailsEndpoint(OrganizationEndpoint):
    permission_classes = (OrganizationSearchEditPermission,)

    def convert_args(self, request: Request, organization_slug, search_id, *args, **kwargs):
        (args, kwargs) = super().convert_args(request, organization_slug, *args, **kwargs)

        # Only allow users to delete their own personal searches OR
        # organization level searches
        org_search = Q(visibility=Visibility.ORGANIZATION)
        personal_search = Q(owner_id=request.user.id, visibility=Visibility.OWNER)

        try:
            search = SavedSearch.objects.get(
                org_search | personal_search,
                organization=kwargs["organization"],
                id=search_id,
            )
        except SavedSearch.DoesNotExist:
            raise ResourceDoesNotExist

        self.check_object_permissions(request, search)
        kwargs["search"] = search

        return (args, kwargs)

    def put(self, request: Request, organization: Organization, search: SavedSearch) -> Response:
        """
        Updates a saved search
        """
        if request.access.has_scope("org:write"):
            serializer = OrganizationSearchAdminSerializer(data=request.data)
        else:
            serializer = OrganizationSearchMemberSerializer(data=request.data)

        if not serializer.is_valid():
            return Response(serializer.errors, status=400)

        result = serializer.validated_data

        if (
            SavedSearch.objects
            # Query duplication for pinned searches is fine, exlcuded these
            .exclude(visibility=Visibility.OWNER_PINNED)
            .exclude(id=search.id)
            .filter(Q(is_global=True) | Q(organization=organization), query=result["query"])
            .exists()
        ):
            return Response(
                {"detail": "Query {} already exists".format(result["query"])}, status=400
            )

        search.update(**result)
        return Response(serialize(search, request.user))

    def delete(self, request: Request, organization: Organization, search: SavedSearch) -> Response:
        """
        Permanently remove a saved search.
        """
        search.delete()
        analytics.record(
            "organization_saved_search.deleted",
            search_type=SearchType(search.type).name,
            org_id=organization.id,
            query=search.query,
        )
        return Response(status=204)

import base64
import binascii
import posixpath
from typing import Union

import sentry_sdk
from django.http.response import FileResponse
from rest_framework.request import Request
from rest_framework.response import Response

from sentry.api.base import region_silo_endpoint
from sentry.api.bases.project import ProjectEndpoint, ProjectReleasePermission
from sentry.api.endpoints.debug_files import has_download_permission
from sentry.api.endpoints.project_release_file_details import ClosesDependentFiles
from sentry.models import ArtifactBundle, ArtifactBundleArchive


class ProjectArtifactBundleFileDetailsMixin:
    @classmethod
    def download_file_from_artifact_bundle(
        cls, file_path: str, archive: ArtifactBundleArchive
    ) -> Union[Response, FileResponse]:
        try:
            fp, headers = archive.get_file(file_path)
            file_info = archive.get_file_info(file_path)
        except Exception:
            # In case we fail here, we want to close the fail before returning.
            archive.close()
            return Response(
                {"error": f"The file {file_path} can't be found in the artifact bundle"},
                status=404,
            )

        response = FileResponse(
            ClosesDependentFiles(fp, archive),
            content_type=headers.get("content-type", "application/octet-stream"),
        )
        response["Content-Length"] = file_info.file_size if file_info is not None else None
        response["Content-Disposition"] = 'attachment; filename="%s"' % posixpath.basename(
            " ".join(file_path.split())
        )

        return response


@region_silo_endpoint
class ProjectArtifactBundleFileDetailsEndpoint(
    ProjectEndpoint, ProjectArtifactBundleFileDetailsMixin
):
    permission_classes = (ProjectReleasePermission,)

    def get(self, request: Request, project, bundle_id, file_id) -> Response:
        """
        Retrieve the file of an artifact bundle
        `````````````````````````````````

        Return details on an individual file within a release.  This does
        not actually return the contents of the file, just the associated
        metadata.

        :pparam string organization_slug: the slug of the organization the
                                          release belongs to.
        :pparam string project_slug: the slug of the project to retrieve the
                                     file of.
        :pparam string bundle_id: the bundle_id of the artifact bundle that
                                    should contain the file identified by file_id.
        :pparam string file_id: the ID of the file to retrieve.
        :auth: required
        """
        if not has_download_permission(request, project):
            return Response(
                {"error": "You don't have the permissions to download this file"}, status=403
            )

        try:
            file_path = base64.urlsafe_b64decode(file_id).decode()
        except (binascii.Error, UnicodeDecodeError):
            return Response(
                {"error": f"The file_id {file_id} is invalid"},
                status=400,
            )

        try:
            artifact_bundle = ArtifactBundle.objects.filter(
                organization_id=project.organization.id,
                bundle_id=bundle_id,
                projectartifactbundle__project_id=project.id,
            )[0]
        except IndexError:
            return Response(
                {
                    "error": f"The artifact bundle with {bundle_id} is not bound to this project or doesn't exist"
                },
                status=400,
            )

        try:
            archive = ArtifactBundleArchive(artifact_bundle.file.getfile(), build_memory_map=False)
        except Exception as exc:
            sentry_sdk.capture_exception(exc)
            return Response(
                {"error": f"The artifact bundle {artifact_bundle.bundle_id} can't be opened"},
                status=400,
            )

        return self.download_file_from_artifact_bundle(file_path, archive)

from typing import Dict, List

from django.utils.functional import cached_property
from rest_framework.request import Request
