def has_team_permission(request, team, scope_map):
    allowed_scopes = set(scope_map.get(request.method, []))
    return any(request.access.has_team_scope(team, s) for s in allowed_scopes)


class TeamPermission(OrganizationPermission):
    scope_map = {
        "GET": ["team:read", "team:write", "team:admin"],
        "POST": ["team:write", "team:admin"],
        "PUT": ["team:write", "team:admin"],
        "DELETE": ["team:admin"],
    }

    def has_object_permission(self, request: Request, view, team):
        has_org_scope = super().has_object_permission(request, view, team.organization)
        if has_org_scope:
            # Org-admin has "team:admin", but they can only act on their teams
            # Org-owners and Org-managers have no restrictions due to team memberships
            return request.access.has_team_access(team)

        return has_team_permission(request, team, self.scope_map)


class TeamEndpoint(Endpoint):
    permission_classes = (TeamPermission,)

    def convert_args(self, request: Request, organization_slug, team_slug, *args, **kwargs):
        try:
            team = (
                Team.objects.filter(organization__slug=organization_slug, slug=team_slug)
                .select_related("organization")
                .get()
            )
        except Team.DoesNotExist:
            raise ResourceDoesNotExist

        if team.status != TeamStatus.ACTIVE:
            raise ResourceDoesNotExist

        self.check_object_permissions(request, team)

        bind_organization_context(team.organization)

        request._request.organization = team.organization

        kwargs["team"] = team
        return (args, kwargs)

from rest_framework.request import Request

from sentry.api.base import Endpoint
from sentry.api.exceptions import ResourceDoesNotExist
from sentry.api.permissions import SentryPermission
from sentry.auth.superuser import is_active_superuser
from sentry.auth.system import is_system_auth
from sentry.models import Organization, OrganizationStatus, User


class UserPermission(SentryPermission):
    def has_object_permission(self, request: Request, view, user=None):
        if user is None:
            user = request.user
        if request.user.id == user.id:
            return True
        if is_system_auth(request.auth):
            return True
        if request.auth:
            return False
        if is_active_superuser(request):
            return True
        return False


class OrganizationUserPermission(UserPermission):
    scope_map = {"DELETE": ["member:admin"]}

    def has_org_permission(self, request: Request, user):
        """
        Org can act on a user account,
        if the user is a member of only one org
        e.g. reset org member's 2FA
        """

        try:
            organization = Organization.objects.get(
                status=OrganizationStatus.ACTIVE, member_set__user_id=user.id
            )

            self.determine_access(request, organization)
            allowed_scopes = set(self.scope_map.get(request.method, []))
            return any(request.access.has_scope(s) for s in allowed_scopes)
        except (Organization.DoesNotExist, Organization.MultipleObjectsReturned):
            return False

    def has_object_permission(self, request: Request, view, user=None):
        if super().has_object_permission(request, view, user):
            return True
        return self.has_org_permission(request, user)


class UserEndpoint(Endpoint):
    """
    The base endpoint for APIs that deal with Users. Inherit from this class to
    get permission checks and to automatically convert user ID "me" to the
    currently logged in user's ID.
    """

    permission_classes = (UserPermission,)

    def convert_args(self, request: Request, user_id, *args, **kwargs):
        if user_id == "me":
            if not request.user.is_authenticated:
                raise ResourceDoesNotExist
            user_id = request.user.id

        try:
            user = User.objects.get(id=user_id)
        except (User.DoesNotExist, ValueError):
            raise ResourceDoesNotExist

        self.check_object_permissions(request, user)

        kwargs["user"] = user
        return args, kwargs

