from sentry import features
from sentry.api.base import region_silo_endpoint
from sentry.api.bases.project import ProjectEndpoint
from sentry.replays.lib.storage import RecordingSegmentStorageMeta, make_filename
from sentry.replays.usecases.reader import download_segment, fetch_segment_metadata


@region_silo_endpoint
class ProjectReplayRecordingSegmentDetailsEndpoint(ProjectEndpoint):
    def get(self, request: Request, project, replay_id, segment_id) -> Response:
        if not features.has(
            "organizations:session-replay", project.organization, actor=request.user
        ):
            return self.respond(status=404)

        segment = fetch_segment_metadata(project.id, replay_id, int(segment_id))
        if not segment:
            return self.respond({"detail": "Replay recording segment not found."}, status=404)

        if request.GET.get("download") is not None:
            return self.download(segment)
        else:
            return self.respond(
                {
                    "data": {
                        "replayId": segment.replay_id,
                        "segmentId": segment.segment_id,
                        "projectId": str(segment.project_id),
                        "dateAdded": segment.date_added.replace(microsecond=0).isoformat(),
                    }
                }
            )

    def download(self, segment: RecordingSegmentStorageMeta) -> StreamingHttpResponse:
        transaction = sentry_sdk.start_transaction(
            op="http.server",
            name="ProjectReplayRecordingSegmentDetailsEndpoint.download_segment",
        )
        segment_bytes = download_segment(
            segment, transaction=transaction, current_hub=sentry_sdk.Hub.current
        )
        segment_reader = BytesIO(segment_bytes)

        response = StreamingHttpResponse(
            iter(lambda: segment_reader.read(4096), b""),
            content_type="application/json",
        )
        response["Content-Length"] = len(segment_bytes)
        response["Content-Disposition"] = f'attachment; filename="{make_filename(segment)}"'
        return response

import sentry_sdk
from drf_spectacular.utils import extend_schema
from rest_framework import serializers
from rest_framework.exceptions import APIException, ParseError
from rest_framework.negotiation import BaseContentNegotiation
from rest_framework.request import Request

from sentry.api.bases.organization import OrganizationEndpoint, OrganizationPermission
from sentry.models import AuthProvider

from .constants import SCIM_400_INVALID_FILTER, SCIM_API_ERROR, SCIM_API_LIST

SCIM_CONTENT_TYPES = ["application/json", "application/json+scim"]
ACCEPTED_FILTERED_KEYS = ["userName", "value", "displayName"]


class SCIMApiError(APIException):
    def __init__(self, detail, status_code=400):
        transaction = sentry_sdk.Hub.current.scope.transaction
        if transaction is not None:
            transaction.set_tag("http.status_code", status_code)
        self.status_code = status_code
        self.detail = {"schemas": [SCIM_API_ERROR], "detail": detail}


class SCIMFilterError(ValueError):
    pass


class SCIMClientNegotiation(BaseContentNegotiation):
    # SCIM uses the content type "application/json+scim"
    # which is just json for our purposes.
    def select_parser(self, request: Request, parsers):
        """
        Select the first parser in the `.parser_classes` list.
        """
        for parser in parsers:
            if parser.media_type in SCIM_CONTENT_TYPES:
                return parser

    def select_renderer(self, request: Request, renderers, format_suffix):
        """
        Select the first renderer in the `.renderer_classes` list.
        """
        for renderer in renderers:
            if renderer.media_type in SCIM_CONTENT_TYPES:
                return (renderer, renderer.media_type)


class SCIMQueryParamSerializer(serializers.Serializer):
    # SCIM API parameters are standardized camelCase by RFC7644.
    # We convert them to snake_case using the source field

    startIndex = serializers.IntegerField(
        min_value=1,
        required=False,
        default=1,
        source="start_index",
        help_text="SCIM 1-offset based index for pagination.",
    )
    count = serializers.IntegerField(
        min_value=0,
        required=False,
        default=100,
        help_text="The maximum number of results the query should return, maximum of 100.",
    )
    filter = serializers.CharField(
        required=False,
        default=None,
        help_text="A SCIM filter expression. The only operator currently supported is `eq`.",
    )
    excludedAttributes = serializers.ListField(
        child=serializers.CharField(),
        required=False,
        default=[],
        source="excluded_attributes",
        help_text="Fields that should be left off of return values. Right now the only supported field for this query is members.",
    )

    def validate_filter(self, filter):
        try:
            filter = parse_filter_conditions(filter)
        except SCIMFilterError:
            raise serializers.ValidationError("invalid filter")
        return filter


class OrganizationSCIMPermission(OrganizationPermission):
    def has_object_permission(self, request: Request, view, organization):
        result = super().has_object_permission(request, view, organization)
        # The scim endpoints should only be used in conjunction with a SAML2 integration
        if not result:
            return result
        try:
            auth_provider = AuthProvider.objects.get(organization_id=organization.id)
        except AuthProvider.DoesNotExist:
            return False
        if not auth_provider.flags.scim_enabled:
            return False

        return True


